{"id":"circulargallery","slug":"circulargallery","name":"Circular Gallery","description":"A cover-flow of image cards bent along an arc — drag, scroll or let it drift; the centre card faces you.","kind":"component","category":"interface","sub":null,"engineCategory":"Carousels","tier":"library","status":"available","stack":["HTML","CSS","JavaScript"],"complexity":"easy","dependencies":[],"bytes":2734,"version":"1.0.0","updated":"2026-09-26","code":"<style>.cgl{width:330px;height:200px;position:relative;perspective:900px;overflow:hidden;font-family:Inter,system-ui,sans-serif;cursor:grab;user-select:none;touch-action:pan-y}\n.cgl.drag{cursor:grabbing}\n.cgl .stage{position:absolute;inset:0;transform-style:preserve-3d}\n.cgl .card{position:absolute;left:50%;top:50%;width:120px;height:150px;margin:-80px 0 0 -60px;border-radius:12px;overflow:hidden;border:1px solid var(--line,#262C34);transition:transform .45s cubic-bezier(.22,1,.36,1),opacity .45s;box-shadow:0 20px 40px -20px rgba(0,0,0,.6)}\n.cgl .card .img{height:120px}\n.cgl .card .cap{height:30px;display:flex;align-items:center;justify-content:center;background:var(--card,#171B22);color:var(--ink,#fff);font:700 11px Inter,sans-serif}\n.cgl .g0 .img{background:linear-gradient(135deg,#7A5CFF,#C0392B)}.cgl .g1 .img{background:linear-gradient(135deg,#5B5BFF,#1E9E6A)}.cgl .g2 .img{background:linear-gradient(135deg,#F5A623,#3366FF)}.cgl .g3 .img{background:linear-gradient(135deg,#7C4DFF,#FF2E88)}.cgl .g4 .img{background:linear-gradient(135deg,#1E9E6A,#5B5BFF)}.cgl .g5 .img{background:linear-gradient(135deg,#3366FF,#7C4DFF)}</style>\n<div class=\"cgl\"><div class=\"stage\" id=\"cgs\"></div></div>\n<script>(function(){var root=document.currentScript.parentNode.querySelector('.cgl');var stage=root.querySelector('#cgs');var labels=['Mountain','Forest','Summit','Ocean','Meadow','Desert'];var cards=labels.map(function(t,i){var d=document.createElement('div');d.className='card g'+i;d.innerHTML='<div class=\"img\"></div><div class=\"cap\">'+t+'</div>';stage.appendChild(d);return d;});var c=0,N=labels.length,timer;function render(){cards.forEach(function(el,i){var o=i-c;if(o>N/2)o-=N;if(o<-N/2)o+=N;el.style.transform='translateX('+(o*72)+'px) translateZ('+(-Math.abs(o)*90)+'px) rotateY('+(-o*38)+'deg)';el.style.opacity=Math.max(0,1-Math.abs(o)*0.34);el.style.zIndex=String(20-Math.abs(o));});}function set(n){c=(n%N+N)%N;render();}cards.forEach(function(el,i){el.addEventListener('click',function(){set(i);reset();});});root.addEventListener('wheel',function(e){e.preventDefault();set(c+(e.deltaY>0?1:-1));reset();},{passive:false});var down=false,sx=0,sc=0;root.addEventListener('pointerdown',function(e){down=true;sx=e.clientX;sc=c;root.classList.add('drag');clearInterval(timer);});window.addEventListener('pointermove',function(e){if(!down)return;set(Math.round(sc-(e.clientX-sx)/80));});window.addEventListener('pointerup',function(){if(down){down=false;root.classList.remove('drag');reset();}});function reset(){clearInterval(timer);timer=setInterval(function(){set(c+1);},2600);}root.addEventListener('mouseenter',function(){clearInterval(timer);});root.addEventListener('mouseleave',reset);render();reset();})();</script>"},
{"id":"infinitespiral","slug":"infinitespiral","name":"Infinite Spiral","description":"Image cards wound into a slowly turning vertical helix, sharp at the centre and fading at the edges.","kind":"component","category":"interface","sub":null,"engineCategory":"Carousels","tier":"library","status":"available","stack":["HTML","CSS","JavaScript"],"complexity":"easy","dependencies":[],"bytes":1588,"version":"1.0.0","updated":"2026-09-26","code":"<style>.isp{width:250px;height:230px;position:relative;perspective:800px;overflow:hidden;font-family:Inter,system-ui,sans-serif;-webkit-mask:linear-gradient(transparent,#000 24%,#000 76%,transparent);mask:linear-gradient(transparent,#000 24%,#000 76%,transparent)}\n.isp .drum{position:absolute;left:50%;top:50%;width:0;height:0;transform-style:preserve-3d;animation:ispspin 14s linear infinite}\n.isp:hover .drum{animation-play-state:paused}\n.isp .card{position:absolute;width:96px;height:96px;margin:-48px 0 0 -48px;border-radius:10px;overflow:hidden;border:1px solid rgba(255,255,255,.12);backface-visibility:hidden;filter:grayscale(1) contrast(1.05)}\n.isp .g0{background:linear-gradient(135deg,#7A5CFF,#C0392B)}.isp .g1{background:linear-gradient(135deg,#5B5BFF,#1E9E6A)}.isp .g2{background:linear-gradient(135deg,#F5A623,#3366FF)}.isp .g3{background:linear-gradient(135deg,#7C4DFF,#FF2E88)}.isp .g4{background:linear-gradient(135deg,#1E9E6A,#5B5BFF)}.isp .g5{background:linear-gradient(135deg,#3366FF,#7C4DFF)}.isp .g6{background:linear-gradient(135deg,#C0392B,#F5A623)}\n@keyframes ispspin{to{transform:rotateY(360deg)}}\n@media(prefers-reduced-motion:reduce){.isp .drum{animation:none}}</style>\n<div class=\"isp\"><div class=\"drum\" id=\"isd\"></div></div>\n<script>(function(){var drum=document.currentScript.parentNode.querySelector('#isd');var N=7,R=150,VS=26;for(var i=0;i<N;i++){var d=document.createElement('div');d.className='card g'+i;var ang=i*(360/N);d.style.transform='rotateY('+ang+'deg) translateZ('+R+'px) translateY('+((i-(N-1)/2)*VS)+'px)';drum.appendChild(d);}})();</script>"}
